package {
    default_applicable_licenses: ["frameworks_compile_libbcc_license"],
}

// Added automatically by a large-scale-change that took the approach of
// 'apply every license found to every target'. While this makes sure we respect
// every license restriction, it may not be entirely correct.
//
// e.g. GPL in an MIT project might only apply to the contrib/ directory.
//
// Please consider splitting the single license below into multiple licenses,
// taking care not to lose any license_kind information, and overriding the
// default license using the 'licenses: [...]' property on targets as needed.
//
// For unused files, consider creating a 'fileGroup' with "//visibility:private"
// to attach the license to, and including a comment whether the files may be
// used in the current project.
// See: http://go/android-license-faq
license {
    name: "frameworks_compile_libbcc_license",
    visibility: [":__subpackages__"],
    license_kinds: [
        "SPDX-license-identifier-Apache-2.0",
        "SPDX-license-identifier-BSD",
        "SPDX-license-identifier-MIT",
        "SPDX-license-identifier-NCSA",
        "legacy_unencumbered",
    ],
    license_text: [
        "NOTICE",
    ],
}

cc_defaults {
    name: "libbcc-defaults",
    defaults: [
        "llvm-defaults",
        "rs-version",
        "libbcc-targets",
    ],

    cflags: [
        "-Wno-unused-parameter",
        "-D__DISABLE_ASSERTS",
    ],

    target: {
        android: {
            cflags: [
                "-DTARGET_BUILD",
            ],
        },
        host: {
            compile_multilib: "first",
            cflags: [
                "-D__HOST__",
            ],
        },
    },

    product_variables: {
        eng: {
            cflags: ["-U__DISABLE_ASSERTS"],
        },
    },

    include_dirs: [
        "frameworks/compile/libbcc/include",
        "frameworks/rs",
    ],
}

//=====================================================================
// Architecture Selection
//=====================================================================
// Note: We should only use -DFORCE_ARCH_CODEGEN on target build.
// For the host build, we will include as many architecture as possible,
// so that we can test the execution engine easily.

cc_defaults {
    name: "libbcc-targets",
    arch: {
        arm: {
            cflags: [
                "-DFORCE_ARM_CODEGEN",
                "-DARCH_ARM_HAVE_NEON",
                "-DARCH_ARM_HAVE_VFP",
                "-DARCH_ARM_HAVE_VFP_D32",
                "-DPROVIDE_ARM64_CODEGEN",
            ],
        },
        arm64: {
            cflags: [
                "-DFORCE_ARM64_CODEGEN",
                "-DARCH_ARM_HAVE_NEON",
                "-DARCH_ARM_HAVE_VFP",
                "-DARCH_ARM_HAVE_VFP_D32",
                "-DDISABLE_CLCORE_NEON",
            ],
        },
    },
    target: {
        android_x86: {
            cflags: ["-DFORCE_X86_CODEGEN"],
        },
        android_x86_64: {
            cflags: ["-DFORCE_X86_64_CODEGEN"],
        },
        arm_on_x86: {
            cflags: [
                "-DPROVIDE_ARM_CODEGEN",
                "-DFORCE_BUILD_ARM",
            ],
        },
        arm_on_x86_64: {
            cflags: [
                "-DPROVIDE_ARM_CODEGEN",
                "-DFORCE_BUILD_ARM",
                "-DPROVIDE_ARM64_CODEGEN",
            ],
        },
    },
}

subdirs = [
    "bcinfo",
    "lib",
    "tools",
]

libbcc_and_slang.text:
